import { useQuery, useQueryClient } from '@tanstack/react-query';

interface Product {
  id: string;
  name: string;
  price: number;
}

const PRODUCTS_KEY = ['products'];

async function fetchProducts(): Promise<Product[]> {
  const res = await fetch('/api/products');
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

/** Reusable hook â€” import this anywhere products are needed */
export function useProducts() {
  return useQuery({
    queryKey: PRODUCTS_KEY,
    queryFn: fetchProducts,
    staleTime: 30_000,
  });
}

/** Single-product hook for detail pages */
export function useProduct(id: string) {
  return useQuery({
    queryKey: ['product', id],
    queryFn: () => fetch(`/api/products/${id}`).then((r) => r.json()),
    enabled: !!id,
  });
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import type { Product } from './useProducts';

async function createProduct(data: {
  name: string;
  price: number;
}): Promise<Product> {
  const res = await fetch('/api/products', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

interface UseCreateProductResult {
  mutate: (data: { name: string; price: number }) => void;
  isPending: boolean;
  isError: boolean;
  error: Error | null;
}

export function useCreateProduct(): UseCreateProductResult {
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: createProduct,
    onSuccess: () => {
      // Invalidate the list so it refetches
      queryClient.invalidateQueries({ queryKey: ['products'] });
    },
  });

  return {
    mutate: mutation.mutate,
    isPending: mutation.isPending,
    isError: mutation.isError,
    error: mutation.error ?? null,
  };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useProduct, PRODUCT_KEY } from './useProducts';

interface CartItem {
  productId: string;
  quantity: number;
}

async function addToCart(item: CartItem): Promise<CartItem> {
  const res = await fetch('/api/cart', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(item),
  });
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

interface UseProductPageResult {
  product: ReturnType<typeof useProduct>['data'];
  productLoading: boolean;
  productError: Error | null;
  addToCart: (quantity: number) => void;
  cartPending: boolean;
}

export function useProductPage(productId: string): UseProductPageResult {
  const queryClient = useQueryClient();

  const productQuery = useProduct(productId);

  const cartMutation = useMutation({
    mutationFn: (quantity: number) => addToCart({ productId, quantity }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cart'] });
    },
  });

  return {
    product: productQuery.data,
    productLoading: productQuery.isLoading,
    productError: productQuery.error ?? null,
    addToCart: (q: number) => cartMutation.mutate(q),
    cartPending: cartMutation.isPending,
  };
}

// Usage in component â€” clean and domain-focused
function ProductPage({ id }: { id: string }) {
  const { product, productLoading, productError, addToCart, cartPending } = useProductPage(id);

  if (productLoading) return <p>Loading productâ€¦</p>;
  if (productError) return <p role="alert">Error: {productError.message}</p>;

  return (
    <div>
      <h1>{product.name}</h1>
      <p>${product.price}</p>
      <button onClick={() => addToCart(1)} disabled={cartPending}>
        {cartPending ? 'Addingâ€¦' : 'Add to Cart'}
      </button>
    </div>
  );
}
